import os, re, json, copy

# Load current session data
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}

for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

gp1_in = G['Demo pair 1 input']
gp1_out = G['Demo pair 1 output']

# Analyze demo pair pattern:
# - Find vertical line of 5s
# - Find horizontal pattern connected to it
# - Project horizontal pattern to fill the rectangle

def find_vertical_5s(grid):
    """Find the column and row range that contains a vertical line of 5s"""
    col = None
    rows = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 5:
                if col is None:
                    col = c
                if col is not None:
                    rows.append(r)
    return col, rows

def extract_horizontal_pattern_at_row(grid, r, c):
    """Extract horizontal pattern starting from position (r,c) going right"""
    result = []
    for cc in range(c, len(grid[0])):
        result.append(grid[r][cc])
        if grid[r][cc] != 5 and cc > c:
            break
    return result

def transform(grid):
    col, rows = find_vertical_5s(grid)
    if col is None or len(rows) == 0:
        return copy.deepcopy(grid)

    # Find the bottom-most 5 in the vertical line
    bottom_row = rows[-1]

    # Check if there's a horizontal pattern at the bottom row
    if bottom_row < len(grid) - 1 and bottom_row + 1 < len(grid):
        # Look for non-zero values to the right of col at bottom_row + 1
        pattern_start = bottom_row + 1
        pattern = extract_horizontal_pattern_at_row(grid, pattern_start, col)

        if pattern and pattern[0] == 5:  # pattern starts with 5
            # Get the non-5 part of the pattern
            pattern_values = pattern[1:] if len(pattern) > 1 else [5]

            # Create output grid
            out = copy.deepcopy(grid)

            # Fill the rectangle: rows, columns (col to col + len(pattern_values))
            for rr in rows:
                for cc, val in enumerate(pattern_values):
                    if col + cc < len(out[0]):
                        out[rr][col + cc] = val

            return out

    return copy.deepcopy(grid)

# Test the function
out1 = transform(gp1_in)
print("Transformed grid 1 matches:", out1 == gp1_out)
print(out1)

